// Evaluador de juguete de asignaciones de roles de Azure RBAC: un rol vale en su scope y en todo lo que cuelga de él.
const SUB = '/subscriptions/11111111-1111-1111-1111-111111111111';
const GRUPO = '/providers/Microsoft.Management/managementGroups/mg-produccion';
const grupoDeLaSuscripcion = { [SUB]: GRUPO };               // la suscripción cuelga de este grupo de administración
const roles = {                                               // permisos simplificados (los reales son cientos de acciones)
  Reader: ['leer'],
  Contributor: ['leer', 'escribir'],
  Owner: ['leer', 'escribir', 'asignar-roles'],
};
const asignaciones = [                                        // principal + rol + scope, los tres elementos de una asignación
  { quien: 'ana',  rol: 'Reader',      scope: SUB },
  { quien: 'beto', rol: 'Contributor', scope: SUB + '/resourceGroups/rg-app-prod' },
  { quien: 'cami', rol: 'Owner',       scope: GRUPO },
];
function ancestros(id) {                                      // el recurso y todos los scopes que lo contienen
  const lista = [id];
  const m = id.match(/^(\/subscriptions\/[^/]+)(\/resourceGroups\/[^/]+)?/i);
  if (m && m[2]) lista.push(m[1] + m[2]);
  if (m) lista.push(m[1]);
  if (m && grupoDeLaSuscripcion[m[1]]) lista.push(grupoDeLaSuscripcion[m[1]]);
  return lista;
}
function puede(quien, accion, recurso) {
  const arriba = ancestros(recurso);
  return asignaciones.some(a => a.quien === quien && arriba.includes(a.scope) && roles[a.rol].includes(accion));
}
const cuenta = SUB + '/resourceGroups/rg-app-prod/providers/Microsoft.Storage/storageAccounts/fotosprod01';
const vmTest = SUB + '/resourceGroups/rg-app-test/providers/Microsoft.Compute/virtualMachines/vm-ensayo';
for (const [nombre, id] of [['cuenta de almacenamiento en rg-app-prod', cuenta], ['máquina virtual en rg-app-test', vmTest]]) {
  console.log('Recurso: ' + nombre);
  for (const quien of ['ana', 'beto', 'cami']) {
    console.log('  ' + quien.padEnd(5) + ['leer', 'escribir', 'asignar-roles'].map(x => x + '=' + (puede(quien, x, id) ? 'sí' : 'no')).join('  '));
  }
}

// Precios de lista en USD leídos de la API pública de precios de Azure el 16-11-2026 (Linux, pago por uso, sin impuestos).
// VM: B2ats v2 (2 vCPU, 1 GiB) por hora. Blob: Hot LRS por GB-mes (primer tramo). Salida a internet por la red global de Microsoft:
// los primeros 100 GB del mes figuran a USD 0 y el siguiente tramo tiene el precio indicado.
const regiones = {
  'eastus (Virginia)':        { vmHora: 0.0094, gbBlob: 0.0208,  gbSalida: 0.087 },
  'chilecentral (Santiago)':  { vmHora: 0.0132, gbBlob: 0.02576, gbSalida: 0.087 },
  'brazilsouth (São Paulo)':  { vmHora: 0.0151, gbBlob: 0.0326,  gbSalida: 0.181 },
};
const caso = { horas: 730, gbBlob: 100, gbSalida: 500, gbSalidaGratis: 100 };   // caso inventado
const totales = {};
for (const [region, p] of Object.entries(regiones)) {
  const vm = p.vmHora * caso.horas;
  const blob = p.gbBlob * caso.gbBlob;
  const salida = Math.max(0, caso.gbSalida - caso.gbSalidaGratis) * p.gbSalida;
  totales[region] = vm + blob + salida;
  console.log(region.padEnd(26) + ' VM ' + vm.toFixed(2) + ' | Blob ' + blob.toFixed(2) + ' | salida ' + salida.toFixed(2) + ' | total USD ' + totales[region].toFixed(2));
}
const base = totales['eastus (Virginia)'];
for (const [region, t] of Object.entries(totales)) {
  if (region.startsWith('eastus')) continue;
  console.log(region + ' vs Virginia: ' + (t / base >= 1 ? '+' : '') + ((t / base - 1) * 100).toFixed(0) + ' %');
}
